&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;EN-US&quot;&gt;Mission Brief&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW114497174 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun CommentStart CommentHighlightPipeRest CommentHighlightRest SCXW114497174 BCX8&quot;&gt;&lt;span class=&quot;TextRun SCXW39738089 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW39738089 BCX0&quot;&gt;&lt;span class=&quot;TextRun SCXW266577432 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;As a&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt; Launch Vehicle &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;Working Student&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt; in the Reusability Program, you &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;support the engineering team in the preliminary design &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;and coordination of reusability experiments&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;. Initially supporting ESA reusability studies, you translate Spectrum test insights into &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;architecture&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;NoBreakHyphenBlob BlobObject DragDrop SCXW266577432 BCX0&quot;&gt;‑&lt;/span&gt;&lt;span class=&quot;TextRun SCXW266577432 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;level performance assessment&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;s, design constraints and development targets&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;. &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;You perform preliminary sizing of &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;structural interfaces&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;, instrumentation layouts, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;actuator systems, mechanisms&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt; and interface with the specialist departments (&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;Launch Vehicle structures&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;AIT&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW266577432 BCX0&quot;&gt;) to ensure compatibility and compliance with system constraints.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW266577432 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt; &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW39738089 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW114497174 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun CommentStart CommentHighlightPipeRest CommentHighlightRest SCXW114497174 BCX8&quot;&gt;Your Role in Our Space Mission&lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentHighlightRest SCXW114497174 BCX8&quot;&gt;:&lt;/span&gt;&lt;/span&gt;&lt;span lang=&quot;EN-US&quot;&gt;&lt;span class=&quot;EOP CommentHighlightPipeRest SCXW114497174 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Reusability upgrade system design: architectural design, constrained by mission objectives, pre-existing architecture and available components.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Support program&lt;/span&gt;‑&lt;span data-contrast=&quot;auto&quot;&gt;level decisions by delivering structured results, trade-offs, and data&lt;/span&gt;‑&lt;span data-contrast=&quot;auto&quot;&gt;driven recommendations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;After becoming familiar with existing architecture, interface with Launch Vehicle Structures and AIT departments on system requirements, avionics system capabilities, instrumentation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Define requirements for ground test rigs and instrumentation setups&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Analyse test data and document results.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Support rapid prototyping and testing activities.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;EN-US&quot;&gt;&lt;span class=&quot;EOP CommentHighlightPipeRest SCXW114497174 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;Qualification Checklist&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
