&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Hands-on, proactive and adaptable working style, with the ability to manage changing tasks and priorities.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong communication and teamwork skills, with fluency in English.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
