&lt;p id=&quot;p-rc_4293685bd03f679d-48&quot; data-path-to-node=&quot;5,1,1&quot;&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt; &lt;/span&gt;&lt;/p&gt;
