&lt;p id=&quot;p-rc_4293685bd03f679d-67&quot; data-path-to-node=&quot;5,3,0&quot;&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt;Drive prioritization at a portfolio lev&lt;span class=&quot;citation-530 citation-531&quot;&gt;el, aligning efforts with overall business and product strategy.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p id=&quot;p-rc_4293685bd03f679d-50&quot; data-path-to-node=&quot;5,3,1&quot;&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(102, 120, 140);&quot;&gt; &lt;/span&gt;&lt;/p&gt;
