&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;Work closely with colleagues across Baringa to bring the right expertise to each client&lt;/span&gt;​&lt;/li&gt;
