&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;35&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span class=&quot;TextRun SCXW106167253 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW106167253 BCX0&quot;&gt;Exposure&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW106167253 BCX0&quot;&gt;and experience of delivering&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW106167253 BCX0&quot;&gt;&amp;nbsp;end‑to‑end change, not just stand‑alone analysis&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW106167253 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;35&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span class=&quot;TextRun SCXW131159339 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW131159339 BCX0&quot;&gt;Comfort working alongside digital tools,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW131159339 BCX0&quot;&gt;data&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW131159339 BCX0&quot;&gt;&amp;nbsp;and AI, without needing to be a technical specialist&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW131159339 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;35&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span class=&quot;TextRun SCXW122773806 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW122773806 BCX0&quot;&gt;Strong data literacy&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW122773806 BCX0&quot;&gt;&amp;nbsp;-&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW122773806 BCX0&quot;&gt;able to interpret insights and translate them into clear recommendations&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW122773806 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;35&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span class=&quot;TextRun SCXW48335028 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW48335028 BCX0&quot;&gt;Clear communication skills, particularly when explaining digital or AI‑related concepts to non‑technical stakeholders&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW48335028 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;35&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span class=&quot;TextRun SCXW23792505 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW23792505 BCX0&quot;&gt;A strong focus on outcomes,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW23792505 BCX0&quot;&gt;execution&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW23792505 BCX0&quot;&gt; and impact&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW23792505 BCX0&quot;&gt;&lt;br class=&quot;SCXW23792505 BCX0&quot;&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;What a career at Baringa will give you&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;h3&gt;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;Putting&lt;/span&gt; &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span style=&quot;color: rgb(208, 0, 111);&quot;&gt;People&lt;/span&gt; &lt;/span&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;First.&lt;/span&gt; &lt;/span&gt;&lt;/h3&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Baringa is a People First company and wellbeing is at the forefront of our culture. We recognise the importance of work-life balance and flexible working and provide our staff amazing benefits. Some of these benefits include:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Generous Annual Leave Policy:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We recognise everyone needs a well-deserved break. We provide our employees with 5 weeks of annual leave, fully available at the start of each year. In addition to this, we have introduced our 5-Year Recharge benefit which allows all employees an additional 2 weeks of paid leave after 5 years continuous service.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Flexible Working:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We know that the ‘ideal’ work-life balance will vary from person to person and change at different stages of our working lives. To accommodate this, we have implemented a hybrid working policy and introduced more flexibility around taking unpaid leave.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Corporate Responsibility Days:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; Our world is important to us, so all our employees get 3 every year to help social and environmental causes and increase our impact on the communities that mean the most to us.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Wellbeing Fund:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; We want to encourage all employees to take charge and prioritise their own wellbeing. We’ve introduced our annual People Fund to support this by offering every individual a fund to support and manage their wellbeing through an activity of their choice.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;33&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Profit Share Scheme:&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; All employees participate in the Baringa Group Profit Share Scheme so everyone has a stake in the company’s success.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559685&amp;quot;:1320,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot; data-contrast=&quot;none&quot;&gt;Diversity and Inclusion&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We are proud to be an Equal Opportunity Employer. We believe that creating an environment where everyone feels a sense of belonging is central to our culture and that diversity is paramount to driving creativity, innovation, and value for our clients and for our people.&lt;/span&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot; data-contrast=&quot;none&quot;&gt;An award-winning workplace&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;You can be a part of our ‘Great Place to Work’ – with our commitment to women and well-being in the workplace for all. &lt;/span&gt;&lt;a href=&quot;https://www.baringa.com/en/impact/awards/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Click here&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt; to see some of our recent awards and how we’ve achieved this.&lt;/span&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Using business as a force for good.&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We maintain high standards of environmental performance and transparency, which can be seen through our commitment to Net Zero with our SBTI-verified Scope 1, 2 and 3 emissions reduction targets and our support of the Better Business Act. We report our progress publicly and ensure that we are also externally assessed and scored through organisations like CDP and EcoVadis - helping us to continually identify where we can improve.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We have a long legacy of supporting the communities in which we work, and offer a variety of ways to contribute, by putting people first and creating impact that lasts. Our Corporate Social Responsibility (CSR) agenda is about giving back to the communities in which we live and work by sharing our skills, talent and time. In essence, we aim to empower and encourage everyone in the firm to contribute to the things we care about, and support registered charities and organisations with a clear social or environmental purpose to increase the positive impact they can have.&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;&lt;span style=&quot;color: rgb(208, 0, 111); font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;Join us&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;All applications received will be reviewed by a member of our Talent Acquisition team. We never rely solely on automated screening or AI tools to make hiring decisions. Your application will be considered for employment without regard to race, ethnicity, religion, gender, gender identity or expression, sexual orientation, nationality, disability, age, faith or social background. We do not filter applications by university background and encourage those who have taken alternative educational and career paths to apply. We would like to actively encourage applications from those who identify with less represented and minority groups. We operate an inclusive recruitment process, ensuring reasonable adjustments where needed. Please contact a member of our Recruitment Team to discuss further.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(208, 0, 111); font-family: helvetica, arial, sans-serif;&quot; data-teams=&quot;true&quot;&gt;Baringa Privacy Notices&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For UK &amp;amp; EU&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data will be retained by Baringa for up to two years, in accordance with our &lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-004-ukrpn---uk-recruitment-privacy-notice-pdf.pdf&quot;&gt;UK Recruitment Privacy Notice / &lt;/a&gt;&lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-005-eurpn---eu-recruitment-privacy-notice-pdf.pdf&quot;&gt;EU Recruitment Privacy Notice&lt;/a&gt;, to evaluate your application and meet our legal and reporting obligations. In line with the General Data Protection Regulation (GDPR), you have the right to request access to, rectification, or erasure (subject to legal limitations) of your personal data. For more information, please contact us at &lt;a ----------
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For the USA&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data may be retained by Baringa for up to two years, as outlined in our&amp;nbsp;&lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-007-nerpn-amer--apac-recruitment-privacy-notice-word.pdf&quot;&gt;Recruitment Privacy Notice (AMER &amp;amp; APAC)&lt;/a&gt;, to support the recruitment process and internal reporting requirements. Where applicable, and in accordance with relevant federal and state laws, you may have the right to request access to or correction of your personal information. For further details, please contact &lt;a ----------
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;For Australia &amp;amp; Singapore&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Your personal data will be retained by Baringa for up to two years, in accordance with our &lt;a href=&quot;https://www.baringa.com/globalassets/careers/dp-007-nerpn-amer--apac-recruitment-privacy-notice-word.pdf&quot;&gt;Recruitment Privacy Notice (AMER &amp;amp; APAC)&lt;/a&gt;, to assess your application and meet applicable reporting and legal obligations. In line with the Australian Privacy Act and Singapore’s Personal Data Protection Act (PDPA), you may have rights to access, correct, or request limited deletion of your personal data. For more information, please contact us at &lt;a ----------Find Jobs in United Kingdom on Arbeitnow

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Anduril Industries is a defense technology company with a mission to transform U.S. and allied military capabilities with advanced technology. By bringing the expertise, technology, and business model of the 21st century’s most innovative companies to the defense industry, Anduril is changing how military systems are designed, built and sold. Anduril’s family of systems is powered by Lattice OS, an AI-powered operating system that turns thousands of data streams into a realtime, 3D command and control center. As the world enters an era of strategic competition, Anduril is committed to bringing cutting-edge autonomy, AI, computer vision, sensor fusion, and networking technology to the military in months, not years.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;At Anduril Australia we are developing unmanned systems for subsurface and other domains that will leverage unsupervised autonomy for the delivery of long endurance, multi-mission capability to our customers. These projects, including but not limited to the Extra Large Autonomous Undersea Vehicle (XL-AUV) Program, require Mechanical Engineers with broad experience to drive the delivery a variety of software enabled hardware capabilities to our customers. Anduril Mechanical Engineers rapidly develop expertise in new domains in order to architect, design, deliver, support, and evolve next generation capabilities through the entire product life-cycle.&lt;/p&gt;
&lt;h3&gt;WHAT YOU&#39;LL DO&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Creating detailed plans and specifications for new designs, or derivatives of the Anduril Extra Large Autonomous Undersea Vehicles (XL-AUVs).&lt;/li&gt;
&lt;li&gt;Creating detailed mechanical designs, prototypes and build of complex structures and mechanisms.&lt;/li&gt;
&lt;li&gt;Simulation and analysis of mechanical designs including modal/spectral response analysis.&lt;/li&gt;
&lt;li&gt;Ensure all designs meet internal and external maritime standards.&lt;/li&gt;
&lt;li&gt;Act as a subject matter expert for your areas of expertise as they relate to the delivery of Anduril technology capabilities, including areas such as part design, analysis and material selection.&lt;/li&gt;
&lt;li&gt;Inspecting parts, sub-systems and vehicles to meet design specifications and regulations.&lt;/li&gt;
&lt;li&gt;Design and implement integrated systems, including advanced and sensitive platforms and payloads, that rapidly delivers capability beyond the scope of current systems, with a clear path for both architecture and capability evolution over time.&lt;/li&gt;
&lt;li&gt;Empathise with end-users and drive solutions that balance their needs with external constraints, restrictions and requirements in a multi-stakeholder environment.&lt;/li&gt;
&lt;li&gt;Contribute to the design and development of technology components across Anduril, with the aim of developing components that are re-usable across multiple Anduril product lines.&lt;/li&gt;
&lt;li&gt;Contribute to the design, implementation and execution of development processes for the initial delivery and subsequent iteration of structural hardware, including full lifecycle testing, monitoring and operation.&lt;/li&gt;
&lt;li&gt;Support vehicle and payload manufacturing, testing and deployment. Including DVT (Design Validation Testing) of parts and sub systems.&lt;/li&gt;
&lt;li&gt;Travel to co-locate with end-users, vendors, or the integration and test team up to 20% of the time.&lt;/li&gt;
&lt;li&gt;Work as a member of a multi-disciplinary engineering team, including as a mentor for more Junior Engineers from differing backgrounds.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;REQUIRED QUALIFICATIONS&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s degree in Mechanical Engineering, Aerospace, Naval Architecture, a relevant field, or equivalent experience.&lt;/li&gt;
&lt;li&gt;Professional experience working as a Mechanical Engineer with one or more domains and/or technologies of expertise.&lt;/li&gt;
&lt;li&gt;Capacity to work holistically on complex mechanical systems and structures across design, implementation, operation and sustainment.&lt;/li&gt;
&lt;li&gt;Capacity to act as the technical owner for a complex structural components and assemblies, including stakeholder engagement, requirements definition, roadmap management, team co-ordination, design, implementation, sustainment and evolution.&lt;/li&gt;
&lt;li&gt;Capacity to learn and grow individually while being part of a dynamic team, building cohesion and capacity.&lt;/li&gt;
&lt;li&gt;Ability to obtain and maintain an Australian Government Security Clearance.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;PREFERRED QUALIFICATIONS &amp;amp; EXPERIENCE&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience with the design, analysis, testing, implementation and support of mechanical parts and assemblies.&lt;/li&gt;
&lt;li&gt;Experience working within the maritime defence domains or similar industry e.g. Aerospace or Automotive.&lt;/li&gt;
&lt;li&gt;Experience with NX, FEMAP and Teamcenter or similar CAD, FEA and PLM systems.&lt;/li&gt;
&lt;li&gt;Experience developing Finite Element Method (FEM) models for the purposes of part stress and strain evaluation, and modal analysis.&lt;/li&gt;
&lt;li&gt;Experience with welding, machining, sheet metal, injection molding, composites and/or additive manufacturing.&lt;/li&gt;
&lt;li&gt;Experience within the product delivery lifecycle including manufacturing, system acceptance, deployment, and sustainment.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The salary range for this role is an estimate based on a wide range of compensation factors, inclusive of base salary only. Actual salary offer may vary based on (but not limited to) work experience, education and/or training, critical skills, and/or business considerations. Highly competitive equity grants are included in the majority of full time offers; and are considered part of Anduril&#39;s total compensation package. Additionally, Anduril offers top-tier benefits for full-time employees, including:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3 class=&quot;detailElios&quot;&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Anduril, we invest in our people. Our comprehensive, competitive benefits package (available at little to no cost to employees) ensures you’re supported in health, recovery, and whatever comes next.&amp;nbsp;&lt;/span&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For more information, &lt;a href=&quot;https://www.anduril.com/careers&quot;&gt;Explore Our Benefits&lt;/a&gt;.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;div class=&quot;RichText column1&quot;&gt;
&lt;h3 class=&quot;detailElios&quot;&gt;&lt;strong&gt;Protecting Yourself from Recruitment Scams&lt;/strong&gt;&lt;/h3&gt;
&lt;p class=&quot;detailElios&quot;&gt;Anduril is committed to maintaining the integrity of our Talent acquisition process and the security of our candidates. We&#39;ve observed a rise in sophisticated phishing and fraudulent schemes where individuals impersonate Anduril representatives, luring job seekers with false interviews or job offers. These scammers often attempt to extract payment or sensitive personal information.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;RichText column2&quot;&gt;
&lt;p class=&quot;detailElios&quot;&gt;To ensure your safety and help you navigate your job search with confidence, please keep the following critical points in mind:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p class=&quot;detailElios&quot;&gt;&lt;strong&gt;No Financial Requests:&amp;nbsp;&lt;/strong&gt;Anduril will never solicit payment or demand personal financial details (such as banking information, credit card numbers, or social security numbers) at any stage of our hiring process. Our legitimate recruitment is entirely free for candidates.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Please always verify communications:&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;Direct from Anduril: If you receive an email from one of our recruiters, it will &lt;em&gt;only&lt;/em&gt; come from an ----- address.&lt;/li&gt;
&lt;li&gt;Via Agency Partner: If contacted by a recruiting agency for an Anduril role, their email will clearly identify their agency. If you suspect any suspicious activity, please verify the agency&#39;s authenticity by reaching out to &lt;a ----------
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p class=&quot;detailElios&quot;&gt;&lt;strong&gt;Exercise Caution with Unsolicited Outreach:&lt;/strong&gt;&amp;nbsp;If you receive any communication that appears suspicious, contains grammatical errors, or makes unusual requests, do not engage. Always confirm the sender&#39;s email domain is ----- before providing any personal information or clicking on links.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p class=&quot;detailElios&quot;&gt;&lt;strong&gt;What to Do If You Suspect Fraud:&lt;/strong&gt;&amp;nbsp;Should you encounter any questionable or fraudulent outreach claiming to be from Anduril, please report it immediately to&amp;nbsp;&lt;a ---------- Your proactive caution is invaluable in protecting your personal information and upholding the security and trustworthiness of our recruitment efforts.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;
&lt;h3&gt;&lt;strong&gt;Data Privacy&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;To view Anduril&#39;s candidate data privacy policy, please visit &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&lt;a href=&quot;https://anduril.com/applicant-privacy-notice/&quot;&gt;https://anduril.com/applicant-privacy-notice/&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;By submitting your application, you consent to Anduril Industries using a third-party service provider to conduct pre-employment risk, integrity, and due diligence screening and assessing potential risks as part of your application process. This third-party service provider provides risk-intelligence services that may include analysis of sanctions and watchlists, adverse media, public-record information, and other lawful open-source or commercial data sources. This third-party service provider does not act as a consumer reporting agency. Use of this provider helps to ensure compliance with applicable laws and protect technology, intellectual property, and organizational security.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;Find more English Speaking Jobs in United Kingdom on Arbeitnow

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Anduril Industries is a defense technology company with a mission to transform U.S. and allied military capabilities with advanced technology. By bringing the expertise, technology, and business model of the 21st century’s most innovative companies to the defense industry, Anduril is changing how military systems are designed, built and sold. Anduril’s family of systems is powered by Lattice OS, an AI-powered operating system that turns thousands of data streams into a realtime, 3D command and control center. As the world enters an era of strategic competition, Anduril is committed to bringing cutting-edge autonomy, AI, computer vision, sensor fusion, and networking technology to the military in months, not years.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;ABOUT THE TEAM&lt;/strong&gt;&lt;br&gt;The UK Growth team owns how Anduril builds and converts opportunity in the UK, from market engagement and capture through to contract. We draw on business lines, legal, finance, engineering, programme management expertise from across Anduril to turn capability into contracts. There is no dedicated commercial function in the UK today. This role is the first of its kind, sitting within Growth, and the person in this seat will shape Anduril UK’s commercial approach.&lt;br&gt;&lt;br&gt;&lt;strong&gt;ABOUT THE JOB&lt;/strong&gt;&lt;br&gt;We are looking for a Commercial Officer to join our rapidly growing team in London. You will own and drive the commercial strategy for Anduril&#39;s UK defence business, operating at the intersection of strategy, business development, and deal execution. You will help build and manage a pipeline of government and defence contracts, structure and negotiate deals, and make sure Anduril captures and delivers on opportunities across the MOD.&lt;br&gt;&lt;br&gt;This role demands breadth. You will engage at senior levels with military leaders, government officials, and industry partners, and you will also roll up your sleeves on contract negotiation, pricing, and bid strategy. Anduril&#39;s UK presence is scaling fast and established playbooks for all scenarios do not yet exist, so you must be comfortable with ambiguity and willing to build process where none exists.&lt;br&gt;&lt;br&gt;&lt;strong&gt;WHAT YOU&#39;LL DO&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Develop and execute Anduril&#39;s commercial strategy for the UK defence market, aligned with the company&#39;s growth objectives.&lt;/li&gt;
&lt;li&gt;Work with the wider Business Development team to win opportunities across UK government procurement programmes, direct contracts, and partnership-led bids.&lt;/li&gt;
&lt;li&gt;Develop pricing and margin strategy in coordination with business lines and Global Defence, balancing competitiveness with business sustainability.&lt;/li&gt;
&lt;li&gt;Lead deal structuring, negotiation, and close on major defence contracts, including government-to-government, prime-sub, and teaming arrangements.&lt;/li&gt;
&lt;li&gt;Own the commercial terms of bids and proposals, ensuring alignment with MOD procurement frameworks (e.g. DEFCON, SSRO regulations).&lt;/li&gt;
&lt;li&gt;Manage commercial risk across the portfolio, including export control compliance (ITAR/EAR), offset/industrial participation obligations, and sovereign requirements.&lt;/li&gt;
&lt;li&gt;Serve as the primary commercial interface with MOD Commercial and Defence Procurement&lt;/li&gt;
&lt;li&gt;Build and sustain relationships at senior levels across UK MOD, the NADG, and Front Line Commands.&lt;/li&gt;
&lt;li&gt;Represent Anduril at industry events, defence exhibitions, and government engagements as a credible commercial voice.&lt;/li&gt;
&lt;li&gt;Work closely with Anduril&#39;s US-based commercial and legal teams to align UK deal structures with corporate standards.&lt;/li&gt;
&lt;li&gt;Build the UK commercial function from the ground up – hiring, process, negotiating, deal structuring&lt;/li&gt;
&lt;li&gt;Establish commercial governance frameworks appropriate for a scaling defence business, including approval authorities, contract review processes, and pipeline reporting.&lt;/li&gt;
&lt;li&gt;Act as player-coach: personally leading on marquee pursuits, and, when scale dictates, mobilise and develop a team to handle the growing pipeline.&lt;/li&gt;
&lt;li&gt;Navigate ambiguity and define your own path – the UK operation is scaling rapidly, and established playbooks may not exist yet.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;REQUIRED QUALIFICATIONS&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;10+ years of progressive commercial experience in UK defence, with a track record of winning and delivering government contracts.&lt;/li&gt;
&lt;li&gt;Deep understanding of UK MOD procurement, including DEFCON terms, Single Source regulations, and National Armaments Director Group acquisition processes.&lt;/li&gt;
&lt;li&gt;Proven ability to structure and negotiate complex defence deals, including teaming agreements, subcontracts, and government primes.&lt;/li&gt;
&lt;li&gt;Experience managing export control and technology transfer requirements, including ITAR, EAR, and UK OGEL/SIEL frameworks.&lt;/li&gt;
&lt;li&gt;Credible engaging at SCS2 level and above with senior military and government stakeholders.&lt;/li&gt;
&lt;li&gt;Strong commercial judgement, able to balance risk, margin, and strategic value in deal decisions.&lt;/li&gt;
&lt;li&gt;Comfort working across a diverse range of disciplines including design, engineering, programme management, legal and contracts, supply chain, and finance.&lt;/li&gt;
&lt;li&gt;Ability to be local to or relocate to London, UK.&lt;/li&gt;
&lt;li&gt;SC cleared and eligible to obtain and maintain DV clearance.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;PREFERRED QUALIFICATIONS&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience in autonomous systems or advanced defence technology programmes.&lt;/li&gt;
&lt;li&gt;Familiarity with US defence contracting norms and FMS/DCS frameworks, enabling effective coordination with Anduril&#39;s US headquarters.&lt;/li&gt;
&lt;li&gt;Experience building a commercial function in a high-growth or start-up environment.&lt;/li&gt;
&lt;li&gt;Background in or exposure to industrial participation, offset, SSRO, innovative commercial deal structuring and sovereign capability development programmes.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;UK Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$166,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$220,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The salary range for this role is an estimate based on a wide range of compensation factors, inclusive of base salary only. Actual salary offer may vary based on (but not limited to) work experience, education and/or training, critical skills, and/or business considerations. Highly competitive equity grants are included in the majority of full time offers; and are considered part of Anduril&#39;s total compensation package. Additionally, Anduril offers top-tier benefits for full-time employees, including:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3 class=&quot;detailElios&quot;&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Anduril, we invest in our people. Our comprehensive, competitive benefits package (available at little to no cost to employees) ensures you’re supported in health, recovery, and whatever comes next.&amp;nbsp;&lt;/span&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For more information, &lt;a href=&quot;https://www.anduril.com/careers&quot;&gt;Explore Our Benefits&lt;/a&gt;.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
