&lt;/ul&gt;
&lt;p data-start=&quot;5074&quot; data-end=&quot;5096&quot;&gt;&lt;strong data-start=&quot;5074&quot; data-end=&quot;5096&quot;&gt;Inclusion at Capco&lt;/strong&gt;&lt;/p&gt;
